CREATE TABLE public.hr_shift_settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),shift_id uuid NOT NULL UNIQUE REFERENCES public.hr_shifts(id),employee_id uuid NOT NULL REFERENCES public.hr_employees(id),reason text NOT NULL CHECK(reason IN ('overtime','left_early','sick','no_pay_leave','no_show','annual_leave','swapped','statutory_holiday','late')),settle text NOT NULL CHECK(settle IN ('pay','bank')),hours numeric NOT NULL,amount numeric NOT NULL DEFAULT 0,actual_start time,actual_end time,actual_hours numeric NOT NULL CHECK(actual_hours>=0),note text NOT NULL DEFAULT '',decided_by uuid NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),revision integer NOT NULL DEFAULT 1,source_updated_at timestamptz NOT NULL,employee_status text NOT NULL DEFAULT 'pending' CHECK(employee_status IN ('pending','confirmed','disputed')));
GRANT SELECT ON public.hr_shift_settlements TO authenticated; GRANT ALL ON public.hr_shift_settlements TO service_role; ALTER TABLE public.hr_shift_settlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY settlement_read ON public.hr_shift_settlements FOR SELECT TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()) OR (public.user_has_tenant(auth.uid(),tenant_id) AND EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.id=employee_id AND e.tenant_id=hr_shift_settlements.tenant_id AND e.user_id=auth.uid())));
CREATE TABLE public.hr_work_confirmations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),employee_id uuid NOT NULL REFERENCES public.hr_employees(id),period_start date NOT NULL,period_end date NOT NULL,deadline timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('confirmed','disputed')),message text NOT NULL DEFAULT '',fingerprint text NOT NULL,responded_by uuid NOT NULL,responded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,employee_id,period_start,period_end));
GRANT SELECT ON public.hr_work_confirmations TO authenticated; GRANT ALL ON public.hr_work_confirmations TO service_role; ALTER TABLE public.hr_work_confirmations ENABLE ROW LEVEL SECURITY;
CREATE POLICY work_confirmation_read ON public.hr_work_confirmations FOR SELECT TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()) OR (public.user_has_tenant(auth.uid(),tenant_id) AND EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.id=employee_id AND e.tenant_id=hr_work_confirmations.tenant_id AND e.user_id=auth.uid())));
CREATE TABLE public.hr_payroll_work_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),year integer NOT NULL,month integer NOT NULL CHECK(month BETWEEN 1 AND 12),employee_id uuid NOT NULL REFERENCES public.hr_employees(id),amounts jsonb NOT NULL,baseline jsonb NOT NULL,source_fingerprint text NOT NULL,notes jsonb NOT NULL DEFAULT '{}',changed_by uuid NOT NULL,changed_at timestamptz NOT NULL DEFAULT now(),revision integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,year,month,employee_id));
GRANT SELECT ON public.hr_payroll_work_drafts TO authenticated; GRANT ALL ON public.hr_payroll_work_drafts TO service_role; ALTER TABLE public.hr_payroll_work_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY work_draft_read ON public.hr_payroll_work_drafts FOR SELECT TO authenticated USING(public.payroll_manager(tenant_id,auth.uid()) AND public.people_person_access(tenant_id,employee_id,auth.uid()));
CREATE FUNCTION public.people_work_fingerprint(t uuid,e uuid,first_day date,last_day date) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT md5(COALESCE((SELECT string_agg(to_jsonb(s)::text||COALESCE((to_jsonb(d)-'employee_status')::text,''),'' ORDER BY s.id) FROM public.hr_shifts s LEFT JOIN public.hr_shift_settlements d ON d.shift_id=s.id AND d.tenant_id=t WHERE s.tenant_id=t AND s.employee_id=e AND s.shift_date BETWEEN first_day AND last_day),'')||COALESCE((SELECT string_agg(to_jsonb(a)::text,'' ORDER BY a.id) FROM public.hr_attendance a WHERE a.tenant_id=t AND a.employee_id=e AND a.date BETWEEN first_day AND last_day),'')); $$;
REVOKE ALL ON FUNCTION public.people_work_fingerprint(uuid,uuid,date,date) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.people_work_period(t uuid,e uuid,first_day date,last_day date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE f text;c public.hr_work_confirmations;deadline timestamptz:=((last_day+3)::timestamp AT TIME ZONE 'Asia/Hong_Kong');BEGIN
IF NOT(public.people_person_access(t,e,auth.uid()) OR (public.user_has_tenant(auth.uid(),t) AND NOT EXISTS(SELECT 1 FROM public.user_access_control WHERE tenant_id=t AND user_id=auth.uid() AND status='disabled') AND EXISTS(SELECT 1 FROM public.hr_employees WHERE id=e AND tenant_id=t AND user_id=auth.uid()))) THEN RAISE EXCEPTION 'Person access required';END IF;
IF last_day<first_day OR last_day-first_day>30 THEN RAISE EXCEPTION 'Invalid work period';END IF;f:=public.people_work_fingerprint(t,e,first_day,last_day);SELECT * INTO c FROM public.hr_work_confirmations WHERE tenant_id=t AND employee_id=e AND period_start=first_day AND period_end=last_day;
RETURN jsonb_build_object('fingerprint',f,'deadline',deadline,'status',CASE WHEN c.fingerprint=f THEN c.status WHEN now()>=deadline THEN 'manager_record' ELSE 'pending' END,'message',CASE WHEN c.fingerprint=f THEN c.message END,'responded_at',CASE WHEN c.fingerprint=f THEN c.responded_at END,'shifts',COALESCE((SELECT jsonb_agg(to_jsonb(s)||jsonb_build_object('settlement',CASE WHEN d.source_updated_at=s.updated_at THEN to_jsonb(d) END) ORDER BY s.shift_date,s.start_time) FROM public.hr_shifts s LEFT JOIN public.hr_shift_settlements d ON d.shift_id=s.id AND d.tenant_id=t WHERE s.tenant_id=t AND s.employee_id=e AND s.shift_date BETWEEN first_day AND last_day),'[]'));END $$;
REVOKE ALL ON FUNCTION public.people_work_period(uuid,uuid,date,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.people_work_period(uuid,uuid,date,date) TO authenticated;
CREATE FUNCTION public.rota_settle_shift(t uuid,sid uuid,expected timestamptz,decision jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.hr_shifts;d public.hr_shift_settlements;terms jsonb;v uuid;planned numeric;actual numeric;delta numeric;rate numeric;amount numeric:=0;r text:=decision->>'reason';mode text:=decision->>'settle';BEGIN
SELECT * INTO s FROM public.hr_shifts WHERE id=sid AND tenant_id=t FOR UPDATE;v:=COALESCE(s.venue_id,(SELECT venue_id FROM public.hr_employees WHERE id=s.employee_id AND tenant_id=t));IF s.id IS NULL OR NOT public.rota_manager(t,v,auth.uid()) OR NOT public.people_person_access(t,s.employee_id,auth.uid()) THEN RAISE EXCEPTION 'Rota manager access required';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||extract(year from s.shift_date)::integer||'-'||extract(month from s.shift_date)::integer,0));IF EXISTS(SELECT 1 FROM public.hr_payroll WHERE tenant_id=t AND year=extract(year from s.shift_date) AND month=extract(month from s.shift_date)) OR EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=extract(year from s.shift_date) AND month=extract(month from s.shift_date) AND status='approved') THEN RAISE EXCEPTION 'Saved payroll month is read-only';END IF;
IF s.updated_at IS DISTINCT FROM expected OR s.shift_date>(now() AT TIME ZONE 'Asia/Hong_Kong')::date THEN RAISE EXCEPTION 'Shift changed or has not happened';END IF;SELECT * INTO d FROM public.hr_shift_settlements WHERE shift_id=sid FOR UPDATE;IF COALESCE((decision->>'revision')::integer,0)<>COALESCE(d.revision,0) THEN RAISE EXCEPTION 'Settlement changed; reload';END IF;
IF r NOT IN ('overtime','left_early','sick','no_pay_leave','no_show','annual_leave','swapped','statutory_holiday','late') OR mode NOT IN ('pay','bank') OR length(COALESCE(decision->>'note',''))>3000 THEN RAISE EXCEPTION 'Invalid settlement';END IF;
planned:=CASE WHEN s.shift_type='regular' THEN greatest(0,extract(epoch FROM(s.end_time-s.start_time+CASE WHEN s.end_time<s.start_time THEN interval '24 hours' ELSE interval '0 hours' END))/3600-s.break_minutes/60.0) ELSE 0 END;actual:=(decision->>'actual_hours')::numeric;IF actual IS NULL OR actual::text IN ('NaN','Infinity','-Infinity') OR actual<0 OR actual>24 THEN RAISE EXCEPTION 'Check actual hours';END IF;delta:=actual-planned;
IF r='overtime' AND delta<=0 OR r IN ('left_early','late') AND delta>=0 OR r IN ('sick','no_pay_leave','no_show','annual_leave') AND actual<>0 THEN RAISE EXCEPTION 'Hours do not match the reason';END IF;
IF r IN ('no_show','no_pay_leave','sick','swapped') AND mode<>'pay' OR r='statutory_holiday' AND mode<>'bank' THEN RAISE EXCEPTION 'This settlement is not allowed';END IF;terms:=public.people_terms_at(t,s.employee_id,s.shift_date);IF terms->>'pay_basis'='hour' THEN rate:=NULLIF(terms->>'pay_amount','')::numeric;ELSE rate:=NULLIF(terms->>'hourly_rate','')::numeric;END IF;
IF r='annual_leave' THEN RAISE EXCEPTION 'Approved leave and employee cash election/final entitlement must be verified separately';END IF;IF r='statutory_holiday' THEN RAISE EXCEPTION 'Use alternative statutory holiday leave; hours cannot replace holiday days';END IF;
IF mode='pay' THEN IF r IN ('overtime','left_early','late','no_show','no_pay_leave') THEN IF rate IS NULL THEN RAISE EXCEPTION 'Dated hourly deduction/overtime rate is not recorded';END IF;amount:=round(delta*rate,2);ELSIF r='sick' THEN RAISE EXCEPTION 'Sickness eligibility and average daily wage need a verified leave decision';ELSIF r='swapped' THEN delta:=0;amount:=0;END IF;END IF;
INSERT INTO public.hr_shift_settlements(tenant_id,shift_id,employee_id,reason,settle,hours,amount,actual_start,actual_end,actual_hours,note,decided_by,source_updated_at) VALUES(t,sid,s.employee_id,r,mode,delta,amount,NULLIF(decision->>'actual_start','')::time,NULLIF(decision->>'actual_end','')::time,actual,COALESCE(decision->>'note',''),auth.uid(),s.updated_at)
ON CONFLICT(shift_id) DO UPDATE SET reason=EXCLUDED.reason,settle=EXCLUDED.settle,hours=EXCLUDED.hours,amount=EXCLUDED.amount,actual_start=EXCLUDED.actual_start,actual_end=EXCLUDED.actual_end,actual_hours=EXCLUDED.actual_hours,note=EXCLUDED.note,decided_by=auth.uid(),decided_at=now(),source_updated_at=s.updated_at,revision=hr_shift_settlements.revision+1,employee_status='pending';END $$;
REVOKE ALL ON FUNCTION public.rota_settle_shift(uuid,uuid,timestamptz,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_settle_shift(uuid,uuid,timestamptz,jsonb) TO authenticated;
CREATE FUNCTION public.rota_confirm_my_work(t uuid,first_day date,last_day date,fingerprint text,answer text,message text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e uuid;f text;BEGIN
IF NOT public.user_has_tenant(auth.uid(),t) OR EXISTS(SELECT 1 FROM public.user_access_control WHERE tenant_id=t AND user_id=auth.uid() AND status='disabled') THEN RAISE EXCEPTION 'Staff sign-in required';END IF;IF (SELECT count(*) FROM public.hr_employees WHERE tenant_id=t AND user_id=auth.uid() AND status IN ('active','on_leave'))<>1 THEN RAISE EXCEPTION 'One linked employee required';END IF;SELECT id INTO e FROM public.hr_employees WHERE tenant_id=t AND user_id=auth.uid() AND status IN ('active','on_leave');
IF answer NOT IN ('confirmed','disputed') OR last_day<first_day OR last_day-first_day>30 OR first_day<>date_trunc('week',first_day)::date AND first_day<>date_trunc('month',first_day)::date OR last_day>=(now() AT TIME ZONE 'Asia/Hong_Kong')::date OR length(message)>1000 OR answer='disputed' AND length(trim(message))=0 THEN RAISE EXCEPTION 'Check completed period and response';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||e::text||first_day::text,0));f:=public.people_work_fingerprint(t,e,first_day,last_day);IF f<>fingerprint THEN RAISE EXCEPTION 'Your work record changed; review again';END IF;
INSERT INTO public.hr_work_confirmations(tenant_id,employee_id,period_start,period_end,deadline,status,message,fingerprint,responded_by) VALUES(t,e,first_day,last_day,((last_day+3)::timestamp AT TIME ZONE 'Asia/Hong_Kong'),answer,message,f,auth.uid()) ON CONFLICT(tenant_id,employee_id,period_start,period_end) DO UPDATE SET status=answer,message=EXCLUDED.message,fingerprint=f,responded_by=auth.uid(),responded_at=now();
UPDATE public.hr_shift_settlements SET employee_status=answer WHERE tenant_id=t AND employee_id=e AND shift_id IN(SELECT id FROM public.hr_shifts WHERE tenant_id=t AND employee_id=e AND shift_date BETWEEN first_day AND last_day);END $$;
REVOKE ALL ON FUNCTION public.rota_confirm_my_work(uuid,date,date,text,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_confirm_my_work(uuid,date,date,text,text,text) TO authenticated;